  Hypothesis LIB : lib_call_stmt SEGS L MI S1ST LLVM_ENTRY EMPTY_OBJ LIB_STACK lib_caps LIB_BIGCAP S1TargetRun.TD_LOCALE GLOBAL_LOCALE.

  Definition LS (k cn : nat) : TSet :=
    match k with
    | O => t_emit (W 1 [Z_to_bv 8 0x30; Z_to_bv 8 0x0a]) (t_emit (W 1 (zero_lines (cn - 1))) KX)
    | S _ => t_emit (W 1 (zero_lines (k + cn - 1))) KX
    end.

  Lemma after_printf : forall cn (fx : FPState) k' obj q A R M model,
    (forall (fx : FPState) k obj q A R M model,
       TCORE k 0 obj q A M model -> TREGS (Z.of_nat cn) obj q R ->
       frm_zero (@fp_csr fx) -> (1 <= cn)%nat -> (k + cn <= 4)%nat -> (1 <= k)%nat ->
       srealizes RSEGS (mkCfg (mkst R (Z_to_bv 64 TR_CALLHEAD) M (seg_rom RSEGS)) model) (LS k cn)) ->
    TCORE k' 0 obj q A M model -> TREGS (Z.of_nat (S cn)) obj q R ->
    getr R 1 = Z_to_bv 64 RET_EMIT -> getr R 19 = Z_to_bv 64 0 -> frm_zero (@fp_csr fx) ->
    (1 <= k')%nat -> (k' + cn <= 4)%nat ->
